idlDeclarations.StyleSheet:
// https://drafts.csswg.org/cssom/#the-stylesheet-interface

[
    ExportToWrappedFunction,
    Exposed=Window,
    GenerateIsReachable,
    JSCustomHeader,
    JSCustomMarkFunction,
] interface StyleSheet {
    // FIXME: `type` should not be nullable.
    readonly attribute DOMString? type;
    readonly attribute USVString? href;
    // FIXME: `ownerNode` should be a `(Element or ProcessingInstruction)?`.
    readonly attribute Node? ownerNode;
    // FIXME: `parentStyleSheet` should be a `CSSStyleSheet?`.
    readonly attribute StyleSheet? parentStyleSheet;
    readonly attribute DOMString? title;
    // FIXME: `media` should not be nullable.
    [SameObject, PutForwards=mediaText] readonly attribute MediaList? media;
    attribute boolean disabled;
};

idlDeclarations.StyleSheetList:
// https://drafts.csswg.org/cssom/#the-stylesheetlist-interface

[
    ExportToWrappedFunction,
    Exposed=Window,
    GenerateIsReachable=ImplOwnerNodeRoot,
] interface StyleSheetList {
    // FIXME: `getter` should be `CSSStyleSheet` instead of `StyleSheet`.
    getter StyleSheet? item(unsigned long index);
    readonly attribute unsigned long length;

    // Non-standard API.
    // FIXME: https://drafts.csswg.org/cssom/#the-stylesheetlist-interface does not
    // specify a named getter for StyleSheetList. We should investigate removing this.
    getter CSSStyleSheet (DOMString name);
};

idlDeclarations.CSSStyleSheet:
// https://drafts.csswg.org/cssom/#cssstylesheet
[
    Exposed=Window,
    JSGenerateToNativeObject
] interface CSSStyleSheet : StyleSheet {
    [CallWith=CurrentDocument] constructor(optional CSSStyleSheetInit options = {});

    readonly attribute CSSRule? ownerRule;
    // FIXME: Add [SameObject] below after https://webkit.org/b/163414
    [ImplementedAs=cssRulesForBindings] readonly attribute CSSRuleList cssRules;
    unsigned long insertRule(DOMString rule, optional unsigned long index = 0);
    undefined deleteRule(unsigned long index);

    Promise<CSSStyleSheet> replace(USVString text);
    undefined replaceSync(USVString text);

    // https://drafts.csswg.org/cssom/#legacy-css-style-sheet-members.
    // FIXME: Move these to their own IDL file CSSStyleSheet+Deprecated.idl.
    readonly attribute CSSRuleList rules;
    long addRule(optional DOMString selector = "undefined", optional DOMString style = "undefined", optional unsigned long index);
    undefined removeRule(optional unsigned long index = 0);
};

// https://drafts.csswg.org/cssom/#dictdef-cssstylesheetinit
dictionary CSSStyleSheetInit {
    DOMString baseURL = null;
    (MediaList or DOMString) media = "";
    boolean disabled = false;
};

